#include "hex-image-reassembler.h"
#include <map>
#include <stdexcept>
namespace hex_image {static unsigned nib(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;throw std::invalid_argument("hex");}static std::vector<std::uint8_t> bytes(const std::string& s){if(s.empty()||s[0]!=':'||(s.size()-1)%2)throw std::invalid_argument("record");std::vector<std::uint8_t> b;for(std::size_t i=1;i<s.size();i+=2)b.push_back(static_cast<std::uint8_t>((nib(s[i])<<4)|nib(s[i+1])));if(b.size()<5||b.size()!=static_cast<std::size_t>(b[0])+5)throw std::invalid_argument("count");unsigned sum=0;for(auto x:b)sum=(sum+x)&255;if(sum)throw std::invalid_argument("checksum");return b;}Image reassemble(const std::vector<std::string>& lines){std::uint32_t base=0;bool eof=false;std::map<std::uint32_t,std::uint8_t> data;for(std::size_t n=0;n<lines.size();++n){auto b=bytes(lines[n]);auto count=b[0];auto addr=std::uint32_t(b[1])<<8|b[2];auto type=b[3];if(eof)throw std::invalid_argument("after EOF");if(type==0){for(unsigned i=0;i<count;++i){auto absolute=std::uint64_t(addr+i);if(absolute>0xffffffffULL)throw std::out_of_range("address");auto [it,inserted]=data.emplace(static_cast<std::uint32_t>(absolute),b[4+i]);if(!inserted&&it->second!=b[4+i])throw std::invalid_argument("overlap");}}else if(type==1){if(count||addr)throw std::invalid_argument("EOF");eof=true;}else if(type==4){if(count!=2||addr)throw std::invalid_argument("base");base=(std::uint32_t(b[4])<<24)|(std::uint32_t(b[5])<<16);}else throw std::invalid_argument("type");}if(!eof)throw std::invalid_argument("missing EOF");(void)base;Image image;for(auto [address,value]:data){if(image.spans.empty()||image.spans.back().address+image.spans.back().bytes.size()!=address)image.spans.push_back({address,{}});image.spans.back().bytes.push_back(value);}return image;}}
